package be.winnetrie.mod.simpleserverutilities.network;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record MineRequestPayload(boolean admin,String selectedId,long requestId) implements CustomPacketPayload{public static final Type<MineRequestPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(SimpleServerUtilities.MODID,"mine_request"));public static final StreamCodec<RegistryFriendlyByteBuf,MineRequestPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeBoolean(p.admin);b.writeUtf(p.selectedId,64);b.writeVarLong(p.requestId);},b->new MineRequestPayload(b.readBoolean(),b.readUtf(64),b.readVarLong()));public MineRequestPayload{selectedId=PayloadBounds.string(selectedId,64);requestId=Math.max(0L,requestId);}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
